// ============================================================
async function loadClassDiagnosis() {
  const classCode = document.getElementById('diagClassFilter').value;
  const contentEl = document.getElementById('diagnosisContent');
  if (!classCode) {
    contentEl.innerHTML = '<div class="card"><div class="card-body empty-state"><div class="empty-icon">&#128202;</div><div class="empty-text">请先选择一个班级查看学情</div></div></div>';
    return;
  }
  contentEl.innerHTML = '<div class="card"><div class="card-body" style="text-align:center;padding:40px;"><div class="loading-spinner" style="width:32px;height:32px;border-width:3px;"></div><p style="margin-top:12px;color:var(--text-light);">加载中...</p></div></div>';
  try {
    const data = await API.get('/api/teacher/class-diagnosis/' + encodeURIComponent(classCode));
    if (!data || data.student_count === 0) {
      contentEl.innerHTML = '<div class="card"><div class="card-body empty-state"><div class="empty-icon">&#128229;</div><div class="empty-text">该班级暂无学生</div></div></div>';
      return;
    }
    renderDiagnosis(data);
  } catch (err) {
    contentEl.innerHTML = '<div class="card"><div class="card-body empty-state"><div class="empty-icon">&#10060;</div><div class="empty-text">加载失败：' + escapeHtml(err.message) + '</div></div></div>';
  }
}

function renderDiagnosis(data) {
  const contentEl = document.getElementById('diagnosisContent');
  const kps = data.knowledge_points || [];
  const topWrong = data.top_wrong || [];
  contentEl.innerHTML = '<div class="stats-row"><div class="stat-mini-card"><div class="stat-mini-label">学生总数</div><div class="stat-mini-value">' + (data.student_count || 0) + '</div><div class="stat-mini-sub">人</div></div><div class="stat-mini-card"><div class="stat-mini-label">总答题数</div><div class="stat-mini-value">' + (data.total_answers || 0) + '</div><div class="stat-mini-sub">次</div></div><div class="stat-mini-card"><div class="stat-mini-label">整体正确率</div><div class="stat-mini-value" style="color:' + ((data.overall_accuracy || 0) >= 60 ? 'var(--success)' : 'var(--warning)') + ';">' + (data.overall_accuracy || 0) + '%</div><div class="stat-mini-sub">平均水平</div></div><div class="stat-mini-card"><div class="stat-mini-label">薄弱知识点</div><div class="stat-mini-value" style="color:var(--danger);">' + ((data.weak_points || []).length) + '</div><div class="stat-mini-sub">个需要加强</div></div></div><div class="chart-container" style="margin-bottom:24px;"><div class="chart-title">各知识点平均掌握度</div><canvas id="kpChart" height="280"></canvas></div><div style="display:grid;grid-template-columns:1fr 1fr;gap:24px;margin-bottom:24px;"><div class="chart-container"><div class="chart-title">高频错题 TOP ' + Math.min(topWrong.length, 5) + '</div>' + (topWrong.length === 0 ? '<div style="color:var(--text-light);font-size:13px;padding:20px;text-align:center;">暂无错题数据</div>' : topWrong.slice(0, 5).map((q, i) => '<div class="wrong-q-item"><div class="wq-header"><span class="kp-tag">#' + (i + 1) + ' ' + escapeHtml(q.kp_name || '') + '</span><span class="wq-rate">错误率 ' + (q.wrong_rate || 0) + '%</span></div><div class="wq-text">' + escapeHtml(truncateText(q.question, 80)) + '</div></div>').join('')) + '</div><div class="chart-container"><div class="chart-title">学生学情卡片</div><div id="diagStudentGrid" class="student-grid"></div></div></div>';
  drawKpChart(kps);
  loadDiagStudents(data.class_code);
}

function drawKpChart(kps) {
  const canvas = document.getElementById('kpChart');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const dpr = window.devicePixelRatio || 1;
  const rect = canvas.getBoundingClientRect();
  canvas.width = rect.width * dpr;
  canvas.height = 280 * dpr;
  ctx.scale(dpr, dpr);
  const w = rect.width;
  const h = 280;
  const padding = { top: 20, right: 20, bottom: 60, left: 50 };
  const chartW = w - padding.left - padding.right;
  const chartH = h - padding.top - padding.bottom;
  ctx.clearRect(0, 0, w, h);
  if (kps.length === 0) {
    ctx.fillStyle = '#94a3b8';
    ctx.font = '14px Inter, sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('暂无数据', w / 2, h / 2);
    return;
  }
  // Grid lines
  ctx.strokeStyle = '#e2e8f0';
  ctx.lineWidth = 1;
  ctx.font = '11px Inter, sans-serif';
  ctx.fillStyle = '#94a3b8';
  ctx.textAlign = 'right';
  for (let i = 0; i <= 5; i++) {
    const y = padding.top + (chartH / 5) * i;
    const val = 100 - (i * 20);
    ctx.beginPath();
    ctx.moveTo(padding.left, y);
    ctx.lineTo(w - padding.right, y);
    ctx.stroke();
    ctx.fillText(val + '%', padding.left - 8, y + 4);
  }
  // Bars
  const barW = Math.min(40, (chartW / kps.length) * 0.6);
  const gap = chartW / kps.length;
  kps.forEach((kp, i) => {
    const x = padding.left + gap * i + (gap - barW) / 2;
    const score = kp.avgScore || 0;
    const barH = (score / 100) * chartH;
    const y = padding.top + chartH - barH;
    // Bar with rounded top
    ctx.fillStyle = kp.color || '#6366f1';
    ctx.beginPath();
    const r = 4;
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + barW - r, y);
    ctx.quadraticCurveTo(x + barW, y, x + barW, y + r);
    ctx.lineTo(x + barW, y + barH);
    ctx.lineTo(x, y + barH);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.fill();
    // Score text
    ctx.fillStyle = '#475569';
    ctx.font = 'bold 11px Inter, sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText(score + '', x + barW / 2, y - 6);
    // Label
    ctx.fillStyle = '#64748b';
    ctx.font = '11px Inter, sans-serif';
    ctx.textAlign = 'center';
    const label = kp.kp_name.length > 6 ? kp.kp_name.substring(0, 6) + '...' : kp.kp_name;
    ctx.save();
    ctx.translate(x + barW / 2, h - padding.bottom + 12);
    ctx.rotate(-0.4);
    ctx.fillText(label, 0, 0);
    ctx.restore();
  });
}

async function loadDiagStudents(classCode) {
  try {
    const data = await API.get('/api/teacher/students?classCode=' + encodeURIComponent(classCode));
    const students = data.students || [];
    const grid = document.getElementById('diagStudentGrid');
    if (!grid) return;
    if (students.length === 0) {
      grid.innerHTML = '<div style="color:var(--text-light);font-size:13px;">暂无学生</div>';
      return;
    }
    grid.innerHTML = students.map(s => {
      const rate = s.correct_rate || 0;
      let color = '#94a3b8';
      let label = '未测评';
      if ((s.total_answers || 0) > 0) {
        if (rate >= 80) { color = '#10b981'; label = '优秀'; }
        else if (rate >= 60) { color = '#6366f1'; label = '良好'; }
        else if (rate >= 40) { color = '#f59e0b'; label = '及格'; }
        else { color = '#ef4444'; label = '需加强'; }
      }
      return '<div class="student-card" onclick="viewStudentDetail(' + s.id + ')"><div class="sc-avatar">' + getInitials(s.username) + '</div><div class="sc-name">' + escapeHtml(s.username) + '</div><div class="sc-score" style="color:' + color + ';">' + ((s.total_answers || 0) > 0 ? rate + '%' : '-') + '</div><div class="sc-label">' + label + ' · ' + (s.total_answers || 0) + '题</div></div>';
    }).join('');
  } catch (err) { console.error('Load diag students error:', err); }
}

// ============================================================
// 7. 个人中心 - 修改密码
// ============================================================
async function changePassword() {
  const oldPwd = document.getElementById('oldPassword').value;
  const newPwd = document.getElementById('newPassword').value;
  const confirmPwd = document.getElementById('confirmPassword').value;
  if (!oldPwd) { showToast('请输入当前密码', 'warning'); return; }
  if (!newPwd) { showToast('请输入新密码', 'warning'); return; }
  if (newPwd.length < 6) { showToast('新密码长度不能少于6位', 'warning'); return; }
  if (newPwd !== confirmPwd) { showToast('两次输入的新密码不一致', 'warning'); return; }
  try {
    await API.put('/api/auth/password', { oldPassword: oldPwd, newPassword: newPwd });
    showToast('密码修改成功', 'success');
    document.getElementById('oldPassword').value = '';
    document.getElementById('newPassword').value = '';
    document.getElementById('confirmPassword').value = '';
  } catch (err) { showToast(err.message, 'error'); }
}
